    fetchProduct();
  }, []);

  return (
    &lt;Navigator&gt;
      &lt;Screen name="HelloWorld" title="Hello World!"&gt;
        &lt;List
          imageDisplayStrategy='always'
          data={data}
        /&gt;
      &lt;/Screen&gt;
    &lt;/Navigator&gt;
  )
}

