import React from 'react';

import {
  Button,
  reactExtension,
  useApi,
} from '@shopify/ui-extensions-react/point-of-sale';

const ReturnActionMenuItem = () =&gt; {
  const api = useApi&lt;'pos.return.post.action.menu-item.render'&gt;();
  return (
    &lt;Button
      onPress={() =&gt; {
        api.action.presentModal();
      }}
    /&gt;
  );
};

export default reactExtension('pos.return.post.action.menu-item.render', () =&gt; (
  &lt;ReturnActionMenuItem /&gt;
));

import {Button, extension} from '@shopify/ui-extensions/point-of-sale';

export default extension(
  'pos.return.post.action.menu-item.render',
  (root, api) =&gt; {
    const button = root.createComponent(Button, {
      onPress: () =&gt; {
        api.action.presentModal();
      },
    });

    root.append(button);
  },
);

import React from 'react';

import {
  Navigator,
  Screen,
  ScrollView,
  Text,
  reactExtension,
  useApi,
} from '@shopify/ui-extensions-react/point-of-sale';

const ReturnAction = () =&gt; {
  const api = useApi&lt;'pos.return.post.action.render'&gt;();
  return (
    &lt;Navigator&gt;
      &lt;Screen name="ReturnDetails" title="Return Details"&gt;
        &lt;ScrollView&gt;
          &lt;Text&gt;{`Order ID: ${api.order.id}`}&lt;/Text&gt;
        &lt;/ScrollView&gt;
      &lt;/Screen&gt;
    &lt;/Navigator&gt;
  );
};

export default reactExtension('pos.return.post.action.render', () =&gt; (
  &lt;ReturnAction /&gt;
));

import {
  Navigator,
  Screen,
  ScrollView,
  Text,
  extension,
} from '@shopify/ui-extensions/point-of-sale';

export default extension('pos.return.post.action.render', (root, api) =&gt; {
  const navigator = root.createComponent(Navigator);
  const screen = root.createComponent(Screen, {
    name: 'ReturnDetails',
    title: 'Return Details',
  });
  const scrollView = root.createComponent(ScrollView);
  const text = root.createComponent(Text);

  text.append(`Order ID: ${api.order.id}`);
  scrollView.append(text);
  screen.append(scrollView);
  navigator.append(screen);
  root.append(navigator);
});

import React from 'react';

import {
  POSBlock,
  POSBlockRow,
  Text,
  reactExtension,
  useApi,
} from '@shopify/ui-extensions-react/point-of-sale';

const ReturnBlock = () =&gt; {
  const api = useApi&lt;'pos.return.post.block.render'&gt;();
  return (
    &lt;POSBlock
      action={{title: 'View return details', onPress: api.action.presentModal}}
    &gt;
      &lt;POSBlockRow&gt;
        &lt;Text&gt;{'Return block extension'}&lt;/Text&gt;
        &lt;Text&gt;{`Order ID: ${api.order.id}`}&lt;/Text&gt;
      &lt;/POSBlockRow&gt;
    &lt;/POSBlock&gt;
  );
};

export default reactExtension('pos.return.post.block.render', () =&gt; (
  &lt;ReturnBlock /&gt;
));

import {
  POSBlock,
  POSBlockRow,
  Text,
  extension,
} from '@shopify/ui-extensions/point-of-sale';

export default extension('pos.return.post.block.render', (root, api) =&gt; {
  const block = root.createComponent(POSBlock, {
    action: {title: 'View return details', onPress: api.action.presentModal},
  });

  const mainText = root.createComponent(Text);
  mainText.append('Return block extension');

  const subtitleText = root.createComponent(Text);
  subtitleText.append(`Order ID: ${api.order.id}`);

  const blockMainRow = root.createComponent(POSBlockRow);
  blockMainRow.append(mainText);

  const blockSubtitleRow = root.createComponent(POSBlockRow);
  blockSubtitleRow.append(subtitleText);
  block.append(blockMainRow);
  block.append(blockSubtitleRow);

  root.append(block);
});

